/** @file RandomPotentialHistoryFixture.h
 * @brief Load reproducible random initial values for the two stored potential time levels.
 * @details A fixture contains A_nm1 and A_n, each with scalar potential in component zero
 * and Cartesian vector potential in components 1 through 3. The samples are generated by
 * GenerateRandomPotentialHistoryFixtures.py, not by a platform-specific C++ random engine.
 * The data does not select boundary conditions: the receiving solver supplies periodic
 * or Mur boundaries and prepares the ghosts after the owned samples have been loaded.
 */
#pragma once
#include <array>
#include <bit>
#include <fstream>
#include <vector>

#include "BoxSetup.h"

namespace chdr::solver::test {
    /** @brief Read exactly two four-component binary64 histories from a generated fixture.
     * The generator defines little-endian data ordered by level, component, x, y, z.
     * A missing or truncated file is a test failure, not a replacement random seed.
     */
    inline std::vector<double> readRandomPotentialHistoryFixture(const char* name,
                                                                 std::array<int, 3> n) {
        static_assert(std::endian::native == std::endian::little);
        std::vector<double> data(8 * std::size_t(n[0]) * n[1] * n[2]);
        std::ifstream input(
            std::string(CHDR_RANDOM_POTENTIAL_HISTORY_FIXTURE_DIR) + "/" + name + ".bin",
            std::ios::binary);
        if (!input.read(reinterpret_cast<char*>(data.data()), data.size() * sizeof(double))
            || input.peek() != std::char_traits<char>::eof())
            throw std::runtime_error(
                "Missing or incorrectly sized random potential-history fixture");
        return data;
    }

    /** @brief Copy global random samples to owned cells and complete both loaded histories.
     * @param solver Destination solver; its A_nm1 and A_n fields must already be allocated.
     * @param name Fixture filename without the .bin suffix, relative to the generated directory.
     * @param n Global cell counts in x, y and z; must match the fixture and solver layout.
     * @param innerOnly If true, zero the two outermost owned-cell layers at each end of every
     * nonperiodic axis. Periodic axes are not masked.
     * @details Global indexing gives identical samples under every decomposition.
     * Ghost values are supplied only by the solver's normal history preparation.
     * This loads initial data; it neither advances time nor reconstructs electric/magnetic fields.
     */
    template <class Solver>
    void loadRandomPotentialHistoryFixture(Solver& solver, const char* name, std::array<int, 3> n,
                                           bool innerOnly = false) {
        const auto data         = readRandomPotentialHistoryFixture(name, n);
        const std::size_t cells = std::size_t(n[0]) * n[1] * n[2];
        unsigned level          = 0;
        for (auto* field : {&solver.A_nm1, &solver.A_n}) {
            *field    = 0.;
            auto host = field->getHostMirror();
            Kokkos::deep_copy(host, field->getView());
            const auto local = field->getLayout().getLocalNDIndex();
            for (int i = 1; i <= int(local[0].length()); ++i)
                for (int j = 1; j <= int(local[1].length()); ++j)
                    for (int k = 1; k <= int(local[2].length()); ++k) {
                        const std::array<int, 3> g{i + local[0].first() - 1,
                                                   j + local[1].first() - 1,
                                                   k + local[2].first() - 1};
                        bool zero = false;
                        for (unsigned d = 0; d < 3; ++d)
                            zero |= innerOnly && !field->getLayout().isPeriodic(d)
                                    && (g[d] < 2 || g[d] >= n[d] - 2);
                        const std::size_t index = (std::size_t(g[0]) * n[1] + g[1]) * n[2] + g[2];
                        for (unsigned q = 0; q < 4; ++q)
                            host(i, j, k)[q] = zero ? 0. : data[(4 * level + q) * cells + index];
                    }
            Kokkos::deep_copy(field->getView(), host);
            ++level;
        }
        solver.prepareHistories();
    }
}  // namespace chdr::solver::test
